// Generated by EldUI from the design file — deterministic export (no AI).
// Motion runtime: in-view / click triggers, text splitting and the anime.js (MIT) animations.
import * as motionAnime from 'animejs'

const motionReduced = typeof window !== 'undefined' && window.matchMedia('(prefers-reduced-motion: reduce)').matches

/** Stagger position of each of n items. */
function motionOrder(n, from) {
  const idx = Array.from({ length: n }, (_, i) => i)
  if (from === 'last') return idx.map((i) => n - 1 - i)
  if (from === 'center') return idx.map((i) => Math.abs(i - (n - 1) / 2))
  if (from === 'random') {
    const order = idx.slice().sort(() => Math.random() - 0.5)
    const out = []
    order.forEach((item, pos) => (out[item] = pos))
    return out
  }
  return idx
}

/** Wraps the words (and chars) of a text in spans; CSS staggers them with --i. */
function motionSplit(el, by, from) {
  if (el.dataset.motionSplit) return
  el.dataset.motionSplit = by
  const label = document.createElement('span')
  label.textContent = el.textContent
  label.style.cssText = 'position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap'
  const words = []
  const chars = []
  const walk = (node) => {
    for (const child of Array.from(node.childNodes)) {
      if (child.nodeType === 1) walk(child)
      if (child.nodeType !== 3) continue
      const frag = document.createDocumentFragment()
      for (const part of child.textContent.split(/(\s+)/)) {
        if (!part) continue
        if (/^\s+$/.test(part)) {
          frag.append(part)
          continue
        }
        const word = document.createElement('span')
        word.className = 'eldui-word'
        word.setAttribute('aria-hidden', 'true')
        words.push(word)
        if (by === 'chars') {
          for (const ch of Array.from(part)) {
            const c = document.createElement('span')
            c.className = 'eldui-char'
            c.textContent = ch
            chars.push(c)
            word.append(c)
          }
        } else word.textContent = part
        frag.append(word)
      }
      child.replaceWith(frag)
    }
  }
  walk(el)
  el.append(label)
  const items = by === 'chars' ? chars : words
  motionOrder(items.length, from).forEach((pos, i) => items[i].style.setProperty('--i', String(pos)))
}

/** Calls enter() when the element's top crosses c.start (% of the viewport). */
function motionInView(el, c, enter, leave) {
  const once = c.once !== false
  const io = new IntersectionObserver(
    (entries) => {
      entries.forEach((e) => {
        if (e.isIntersecting) {
          enter()
          if (once) io.disconnect()
        } else if (!once && e.boundingClientRect.top > 0) leave()
      })
    },
    { rootMargin: '0px 0px -' + (100 - (c.start ?? 85)) + '% 0px' },
  )
  io.observe(el)
  return () => io.disconnect()
}

/** CSS animations (paused by the stylesheet) started by a trigger. */
function motionCss(el, c) {
  const anims = () => el.getAnimations({ subtree: true }).filter((a) => a.animationName === c.name)
  const play = () =>
    anims().forEach((a) => {
      a.currentTime = 0
      a.play()
    })
  if (c.trigger === 'click') {
    el.addEventListener('click', play)
    return () => el.removeEventListener('click', play)
  }
  if (c.trigger === 'in-view') return motionInView(el, c, play, () => anims().forEach((a) => (a.pause(), (a.currentTime = 0))))
  return null
}

function motionEase(e, duration) {
  const named = { ease: [0.25, 0.1, 0.25, 1], 'ease-in': [0.42, 0, 1, 1], 'ease-out': [0, 0, 0.58, 1], 'ease-in-out': [0.42, 0, 0.58, 1] }
  e = (e || 'ease').trim()
  if (named[e]) return motionAnime.cubicBezier(...named[e])
  let m = /^cubic-bezier\(([^)]+)\)$/.exec(e)
  if (m) return motionAnime.cubicBezier(...m[1].split(',').map(Number))
  m = /^spring\(([^)]+)\)$/.exec(e)
  if (m) return motionAnime.spring({ bounce: Number(m[1]), duration })
  m = /^steps\((\d+)(?:,\s*([a-z-]+))?\)$/.exec(e)
  if (m) return motionAnime.steps(Number(m[1]), m[2] === 'start' || m[2] === 'jump-start')
  return 'linear'
}

/** anime.js animation: scroll-scrubbed, line splitting or spring easing. */
function motionAnimate(el, c) {
  if (motionReduced) return null
  const A = motionAnime
  const keyframes = {}
  let draws = false
  for (const key in c.keyframes) {
    const f = Object.assign({}, c.keyframes[key])
    if (f.ease) f.ease = motionEase(f.ease, c.duration)
    if ('strokeDashoffset' in f) draws = true
    keyframes[key] = f
  }
  if (draws) el.style.strokeDasharray = '1'
  let anim = null
  const autoplay = () =>
    c.trigger === 'scroll'
      ? A.onScroll({ target: el, enter: (c.start ?? 100) + '% top', leave: (c.end ?? 0) + '% ' + (c.endEdge || 'bottom'), sync: true })
      : c.trigger === 'load'
  const build = (targets) => {
    anim = A.animate(targets, {
      keyframes,
      duration: c.duration,
      delay: c.stagger ? A.stagger(c.stagger, { start: c.delay || 0, from: c.from || 'first' }) : c.delay || 0,
      ease: motionEase(c.ease, c.duration),
      loop: c.iterations === 0 ? true : (c.iterations || 1) - 1,
      alternate: /alternate/.test(c.direction || ''),
      reversed: /reverse/.test(c.direction || ''),
      autoplay: autoplay(),
    })
    // triggered later: show the first keyframe until then
    if (c.trigger !== 'load' && c.trigger !== 'scroll') anim.seek(0)
    return anim
  }
  let split = null
  if (c.target === 'chars' || c.target === 'words' || c.target === 'lines') {
    split = A.splitText(el, { lines: c.target === 'lines', words: c.target !== 'lines', chars: c.target === 'chars' })
    split.addEffect((s) => build(c.target === 'chars' ? s.chars : c.target === 'words' ? s.words : s.lines))
  } else build(c.target === 'children' ? Array.from(el.children) : el)
  const play = () => anim && anim.restart()
  let off = null
  if (c.trigger === 'hover' || c.trigger === 'click') {
    const ev = c.trigger === 'hover' ? 'mouseenter' : 'click'
    el.addEventListener(ev, play)
    off = () => el.removeEventListener(ev, play)
  } else if (c.trigger === 'in-view') {
    off = motionInView(el, c, play, () => anim && (anim.pause(), anim.seek(0)))
  }
  return () => {
    if (off) off()
    if (anim) anim.revert()
    if (split) split.revert()
  }
}

/** Sets up the animations of one element; returns a cleanup function. */
function motionSetup(el, configs) {
  const css = configs.filter((c) => c.engine !== 'anime')
  const by = css.some((c) => c.target === 'chars') ? 'chars' : css.some((c) => c.target === 'words') ? 'words' : null
  if (by) motionSplit(el, by, (css.find((c) => c.target === by) || {}).from)
  const offs = configs.map((c) => (c.engine === 'anime' ? motionAnimate(el, c) : motionCss(el, c)))
  return () => offs.forEach((off) => off && off())
}

/** v-motion="configs": sets the animations up when the element mounts. */
export const vMotion = {
  mounted(el, binding) {
    el._motionOff = motionSetup(el, binding.value || [])
  },
  beforeUnmount(el) {
    if (el._motionOff) el._motionOff()
  },
}
